const SCENES = {"aline":{"2":{"id":"2","kind":"scene","period":"1829","place":"Casa do marido · jantar da elite","title":"Uma Nova Vida","paragraphs":["Aline nasceu em uma família pobre e passou boa parte da infância trabalhando para ajudar em casa. Sua vida muda quando um nobre se interessa por ela e decide se casar com ela.","Agora, Aline vive em uma grande casa e frequenta lugares que antes jamais poderia frequentar. Porém, percebe que sua nova posição tem um preço: ela precisa obedecer ao marido e não possui liberdade para participar da política.","Certo dia, durante um jantar, ela ouve homens da elite comentando sobre mulheres que estão organizando protestos."],"choices":[{"label":"Prestar atenção na conversa","description":"Aline tenta entender quem são aquelas mulheres e por que estão protestando.","next":"3A"},{"label":"Fingir que não está interessada","description":"Aline percebe que demonstrar interesse poderia levantar suspeitas. Ela continua jantando, mas depois tenta descobrir mais sobre o assunto por conta própria.","next":"3B"}]},"3A":{"id":"3A","kind":"scene","period":"1830","place":"Sala de visitas · conversa com a criada","title":"A Descoberta","paragraphs":["Aline consegue ouvir que as mulheres estão reivindicando maior liberdade e direitos. Ela fica surpresa ao perceber que algumas das reclamações são semelhantes às limitações que ela própria enfrenta.","Mais tarde, uma criada comenta que conhece uma das mulheres envolvidas."],"choices":[{"label":"Perguntar diretamente sobre a manifestação","description":"A criada percebe o interesse de Aline e conta que conhece algumas participantes.","next":"4A"},{"label":"Perguntar apenas sobre as mulheres","description":"Aline evita mencionar os protestos diretamente para não levantar suspeitas.","next":"4B"}]},"3B":{"id":"3B","kind":"scene","period":"1830","place":"Cozinha da casa · depois do jantar","title":"Investigando Escondida","paragraphs":["Aline espera até estar sozinha e pergunta discretamente a uma criada sobre os protestos. A mulher fica inicialmente desconfiada, mas percebe que Aline realmente quer entender o que está acontecendo.","Ela conta que algumas das manifestantes se reúnem secretamente."],"choices":[{"label":"Pedir para conhecer uma delas","description":"Aline quer ouvir diretamente das próprias mulheres o motivo da luta.","next":"4C"},{"label":"Pedir apenas informações","description":"Aline prefere não se envolver diretamente, mas quer saber como pode ajudar.","next":"4D"}]},"4A":{"id":"4A","kind":"scene","period":"1831","place":"Rua estreita · encontro escondido","title":"O Primeiro Contato","paragraphs":["A criada leva Aline até uma mulher envolvida nos protestos. Elas conversam escondidas e Aline descobre que o grupo precisa de dinheiro para ajudar outras mulheres."],"choices":[{"label":"Oferecer dinheiro","description":"Aline decide usar parte de sua própria riqueza para ajudar.","next":"5A"},{"label":"Oferecer outro tipo de ajuda","description":"Aline acredita que dinheiro sozinho não resolverá o problema e oferece sua influência social.","next":"5B"}]},"4B":{"id":"4B","kind":"scene","period":"1831","place":"Arredores da casa · informação obtida","title":"Uma Oportunidade","paragraphs":["Aline consegue descobrir onde algumas mulheres se reúnem. Ela ainda não conhece nenhuma delas pessoalmente, mas sabe que poderia entrar em contato."],"choices":[{"label":"Ir pessoalmente à reunião","description":"Ela decide correr o risco para descobrir como pode ajudar.","next":"5C"},{"label":"Mandar uma mensagem secretamente","description":"Ela prefere manter sua identidade protegida enquanto oferece ajuda.","next":"5D"}]},"4C":{"id":"4C","kind":"scene","period":"1831","place":"Casa de uma das líderes do movimento","title":"O Encontro","paragraphs":["Aline conhece uma das líderes do movimento. A mulher explica que muitas participantes têm medo de perder seus empregos ou sofrer consequências por participar dos protestos."],"choices":[{"label":"Oferecer sua casa como esconderijo","description":"Aline acredita que sua posição social poderia proteger algumas mulheres.","next":"5E"},{"label":"Oferecer dinheiro para o grupo","description":"Ela decide usar sua riqueza para financiar o movimento.","next":"5F"}]},"4D":{"id":"4D","kind":"scene","period":"1831","place":"Casa de Aline · observando de longe","title":"De Longe","paragraphs":["Aline ainda não quer se envolver diretamente. Mesmo assim, descobre que algumas mulheres precisam de ajuda para divulgar informações sobre os protestos."],"choices":[{"label":"Ajudar usando seus contatos","description":"Ela pode conversar com pessoas influentes sem revelar que apoia o movimento.","next":"5G"},{"label":"Não se envolver diretamente","description":"Ela decide apenas observar por enquanto e esperar uma oportunidade mais segura.","next":"5H"}]},"5A":{"id":"5A","kind":"scene","period":"1832","place":"Entrega discreta · arredores do centro","title":"O Dinheiro","paragraphs":["Aline decide usar parte do dinheiro que recebe para ajudar o movimento. Ela entrega uma quantia a uma das mulheres, que explica que o dinheiro será usado para ajudar participantes que perderam seus empregos por causa dos protestos.","Poucos dias depois, Aline percebe que seu marido começou a observar mais atentamente seus gastos."],"choices":[{"label":"Continuar enviando dinheiro, mas em quantias menores","next":"6A"},{"label":"Parar de enviar dinheiro e procurar outra forma de ajudar","next":"6B"}]},"5B":{"id":"5B","kind":"scene","period":"1832","place":"Jantar da elite · salão principal","title":"Usando Sua Posição","paragraphs":["Aline percebe que, por ser esposa de um homem importante, consegue ouvir conversas que outras mulheres jamais conseguiriam.","Durante um jantar, alguns homens comentam que o governo está começando a prestar atenção nos protestos."],"choices":[{"label":"Memorizar as informações e avisar as manifestantes","next":"6C"},{"label":"Tentar descobrir mais informações antes de avisá-las","next":"6D"}]},"5C":{"id":"5C","kind":"scene","period":"1832","place":"Reunião clandestina · saída noturna","title":"A Reunião","paragraphs":["Aline decide ir pessoalmente a uma reunião das manifestantes. Ela precisa sair de casa sem que seu marido perceba.","Na reunião, as mulheres discutem uma próxima manifestação."],"choices":[{"label":"Oferecer-se para ajudar na organização","next":"6E"},{"label":"Apenas ouvir e descobrir como poderá ajudar depois","next":"6F"}]},"5D":{"id":"5D","kind":"scene","period":"1832","place":"Casa de Aline · bilhete escrito à mesa","title":"A Mensagem Secreta","paragraphs":["Aline decide não aparecer pessoalmente. Ela escreve uma mensagem para uma das mulheres oferecendo ajuda.","Porém, para enviar a mensagem, ela precisa confiar em alguém para entregá-la."],"choices":[{"label":"Pedir ajuda a uma criada de confiança","next":"6G"},{"label":"Entregar a mensagem pessoalmente, aproveitando uma saída de casa","next":"6H"}]},"5E":{"id":"5E","kind":"scene","period":"1833","place":"Casa de Aline · cômodo reservado","title":"O Esconderijo","paragraphs":["Aline oferece sua própria casa como um lugar onde algumas mulheres poderiam se reunir. Ela acredita que ninguém suspeitaria que uma casa pertencente a um nobre estaria sendo utilizada pelo movimento.","Mas existe um problema: seu marido pode voltar para casa a qualquer momento."],"choices":[{"label":"Esconder as mulheres em um cômodo pouco utilizado","next":"6A"},{"label":"Cancelar a reunião antes que ela aconteça","next":"6B"}]},"5F":{"id":"5F","kind":"scene","period":"1833","place":"Casa de Aline · encontro com o grupo","title":"O Financiamento","paragraphs":["Aline decide financiar parte das atividades do movimento. As mulheres ficam agradecidas, mas avisam que dinheiro não será suficiente para alcançar outras pessoas.","Elas precisam de alguém que consiga fazer o movimento ser ouvido pela elite."],"choices":[{"label":"Usar seus contatos para apresentar as ideias das mulheres","next":"6C"},{"label":"Manter o financiamento em segredo e não se envolver publicamente","next":"6G"}]},"5G":{"id":"5G","kind":"scene","period":"1833","place":"Sarau da elite · conversa discreta","title":"Os Contatos","paragraphs":["Aline começa a conversar discretamente com algumas pessoas da elite. Ela tenta descobrir quem estaria disposto a apoiar mudanças na situação das mulheres.","Durante uma conversa, uma pessoa percebe que Aline parece muito interessada no assunto."],"choices":[{"label":"Admitir que acredita que as mulheres deveriam ter mais direitos","next":"6D"},{"label":"Disfarçar seu interesse e mudar de assunto","next":"6F"}]},"5H":{"id":"5H","kind":"scene","period":"1833","place":"Casa de Aline · batida inesperada na porta","title":"A Distância","paragraphs":["Aline decide não se envolver diretamente. Ela continua observando os acontecimentos enquanto mantém sua vida na elite.","Entretanto, uma das mulheres do movimento aparece inesperadamente em sua casa e pede ajuda.","Ela está sendo procurada e precisa de um lugar para ficar."],"choices":[{"label":"Esconder a mulher em sua casa","next":"6E"},{"label":"Ajudá-la a encontrar outro lugar seguro sem envolvê-la diretamente em sua casa","next":"6H"}]},"6A":{"id":"6A","kind":"scene","period":"1835","place":"Casa de Aline · corredores vigiados","title":"As Suspeitas","paragraphs":["Aline continua ajudando, mas seu marido começa a perceber que algumas coisas estranhas estão acontecendo em sua casa."],"choices":[{"label":"Continuar escondendo suas ações","next":"7A"},{"label":"Diminuir temporariamente sua participação","next":"7B"}]},"6B":{"id":"6B","kind":"scene","period":"1835","place":"Casa de Aline · nova estratégia","title":"Uma Nova Forma de Ajudar","paragraphs":["Aline para de enviar dinheiro e procura outra maneira de ajudar as mulheres sem chamar tanta atenção."],"choices":[{"label":"Usar sua influência social","next":"7B"},{"label":"Ajudar apenas quando surgir uma situação urgente","next":"7C"}]},"6C":{"id":"6C","kind":"scene","period":"1836","place":"Salões e ruas · informações trocadas","title":"Informações Perigosas","paragraphs":["Aline começa a passar informações importantes para as manifestantes. Porém, percebe que está descobrindo coisas que poderiam causar problemas para pessoas poderosas."],"choices":[{"label":"Continuar passando as informações","next":"7B"},{"label":"Parar antes que descubram sua participação","next":"7C"}]},"6D":{"id":"6D","kind":"scene","period":"1836","place":"Sarau da elite · olhares desconfiados","title":"Mais Perto do Perigo","paragraphs":["Ao demonstrar apoio às mulheres, Aline percebe que algumas pessoas da elite começaram a desconfiar de suas opiniões."],"choices":[{"label":"Continuar defendendo discretamente as mulheres","next":"7B"},{"label":"Fingir que mudou de opinião","next":"7C"}]},"6E":{"id":"6E","kind":"scene","period":"1838","place":"Rua do comércio · dia da manifestação","title":"A Manifestação","paragraphs":["Aline passa a ajudar diretamente na organização de uma manifestação. Ela sabe que participar pessoalmente pode colocar sua posição social em risco."],"choices":[{"label":"Participar da manifestação","next":"7D"},{"label":"Ajudar nos preparativos, mas não aparecer","next":"7B"}]},"6F":{"id":"6F","kind":"scene","period":"1838","place":"Bastidores do movimento","title":"Apenas Observando","paragraphs":["Aline continua ajudando sem participar diretamente. Porém, percebe que sua ajuda indireta está começando a fazer diferença."],"choices":[{"label":"Assumir mais responsabilidades","next":"7D"},{"label":"Continuar agindo discretamente","next":"7B"}]},"6G":{"id":"6G","kind":"scene","period":"1838","place":"Casa de Aline · encontros sem testemunhas","title":"O Segredo","paragraphs":["Aline consegue manter seu envolvimento escondido. Porém, quanto mais ajuda, mais difícil fica esconder suas ações."],"choices":[{"label":"Assumir mais riscos","next":"7A"},{"label":"Reduzir sua participação","next":"7C"}]},"6H":{"id":"6H","kind":"scene","period":"1838","place":"Ruas afastadas do centro","title":"Uma Escolha Perigosa","paragraphs":["Aline ajuda as mulheres sem revelar completamente sua identidade. Porém, percebe que alguém pode ter visto suas movimentações."],"choices":[{"label":"Continuar ajudando","next":"7A"},{"label":"Afastar-se temporariamente","next":"7C"}]},"7A":{"id":"7A","kind":"scene","period":"1842","place":"Gabinete do marido · confronto direto","title":"As Suspeitas","paragraphs":["O marido de Aline começa a desconfiar seriamente dela. Ele pergunta diretamente se ela está envolvida com as mulheres que estão organizando os protestos."],"choices":[{"label":"Negar tudo e tentar proteger sua posição social","next":"final-silencio"},{"label":"Contar parte da verdade e admitir que ajudou algumas mulheres","next":"final-descoberta"}]},"7B":{"id":"7B","kind":"scene","period":"1846","place":"Casa de Aline · equilíbrio silencioso","title":"O Equilíbrio","paragraphs":["Aline conseguiu ajudar o movimento sem ser descoberta completamente, mas sabe que não poderá continuar assim para sempre."],"choices":[{"label":"Continuar ajudando, mas de maneira cuidadosa e limitada","next":"final-resistencia"},{"label":"Afastar-se por um tempo para proteger sua posição","next":"final-silencio"}]},"7C":{"id":"7C","kind":"scene","period":"1850","place":"Casa de Aline · longe do movimento","title":"Recuar","paragraphs":["Aline diminui seu envolvimento para evitar que descubram sua participação.","Mesmo assim, ela sabe que outras mulheres continuam precisando de ajuda."],"choices":[{"label":"Voltar a ajudar secretamente, mas sem participar diretamente das manifestações","next":"final-resistencia"},{"label":"Abandonar completamente o movimento","next":"final-silencio"}]},"7D":{"id":"7D","kind":"scene","period":"1852","place":"Praça pública · entre a multidão","title":"A Manifestação","paragraphs":["Aline participa da manifestação. Sua presença é percebida por algumas pessoas da elite.","Agora existe uma chance real de que seu marido descubra."],"choices":[{"label":"Sair da manifestação antes que sua identidade seja descoberta","next":"final-resistencia"},{"label":"Permanecer e assumir publicamente seu apoio às mulheres","next":"final-ruptura"}]},"final-silencio":{"id":"final-silencio","kind":"ending","tier":"silence","label":"Final 1 · Desfecho ruim","title":"O Silêncio","paragraphs":["Aline decide abandonar o movimento para proteger sua posição.","Ela continua vivendo entre a elite e mantém sua segurança, mas precisa voltar a aceitar as limitações que sempre sofreu como mulher.","Com o tempo, percebe que poderia ter ajudado outras mulheres, mas escolheu permanecer em silêncio.","Ela preservou sua posição social, mas abandonou aquilo em que acreditava."]},"final-descoberta":{"id":"final-descoberta","kind":"ending","tier":"discovery","label":"Final 2 · Desfecho ruim","title":"A Descoberta","paragraphs":["Aline admite que estava ajudando as mulheres.","A notícia se espalha rapidamente entre as pessoas próximas ao marido. Sua atitude é vista como uma afronta à posição que deveria ocupar dentro da família e da elite.","O marido rompe publicamente com ela e Aline perde o acesso aos privilégios que havia conquistado através do casamento.","Ela é afastada dos círculos da elite, deixa de ser recebida nos eventos e reuniões que frequentava e perde sua influência social.","Além disso, precisa deixar a casa onde vivia e passa a depender novamente de pessoas de fora daquele círculo para reconstruir sua vida.","Aline não consegue continuar sua atuação como antes, mas sua descoberta mostra que até alguém pertencente à elite poderia questionar as regras impostas às mulheres."]},"final-resistencia":{"id":"final-resistencia","kind":"ending","tier":"resistance","label":"Final 3 · Desfecho mediano","title":"A Resistência Limitada","paragraphs":["Aline decide continuar ajudando, mas evita participar diretamente das manifestações.","Ela usa parte de seus recursos, contatos e influência para ajudar algumas mulheres, sempre tomando cuidado para não ser descoberta.","Sua ajuda consegue melhorar a situação de algumas pessoas, mas ela percebe que suas ações são limitadas pela posição que ocupa e pelo medo de perder tudo.","Aline não abandona completamente sua luta, mas também não consegue enfrentar abertamente a sociedade em que vive."]},"final-ruptura":{"id":"final-ruptura","kind":"ending","tier":"rupture","label":"Final 4 · Desfecho bom","title":"A Ruptura","paragraphs":["Aline decide assumir publicamente seu apoio às mulheres.","Sua decisão provoca conflitos com o marido e ameaça sua posição social, mas ela não volta atrás.","Ela passa a utilizar sua influência para dar espaço às reivindicações das mulheres e começa a participar de forma mais direta das mudanças que defendia.","Aline sabe que poderá perder parte dos privilégios que conquistou, mas finalmente consegue escolher por conta própria como quer viver.","Sua história mostra que sua posição social, que inicialmente parecia uma prisão, também poderia ser usada para abrir espaço para outras mulheres."]}},"joao":{"2":{"id":"2","kind":"scene","period":"1831","place":"Praça da cidade · manhã","title":"Sem Trabalho","paragraphs":["João é um homem branco de 24 anos, pobre e trabalhador. Vive sozinho em uma pequena cidade e perdeu seu emprego como ajudante de um comerciante.","Sem dinheiro suficiente para pagar o aluguel e sem conseguir encontrar outro trabalho fixo, começa a sobreviver fazendo pequenos serviços quando aparecem.","Certa manhã, enquanto procura algum serviço na praça da cidade, um agente da autoridade se aproxima.","— “Qual é a sua ocupação? Onde trabalha e de onde tira seu sustento?”","João explica que perdeu o emprego e que está procurando trabalho. O agente, porém, desconfia de sua situação.","Desde 1830, o Código Criminal do Império previa punições relacionadas à vadiagem. A legislação determinava que uma pessoa sem renda suficiente poderia ser punida caso, depois de advertida pelo Juiz de Paz, não tivesse uma ocupação considerada “honesta e útil”.","O agente pede que João o acompanhe para prestar esclarecimentos."],"choices":[{"label":"Fugir","description":"João percebe uma oportunidade e decide correr antes que o agente consiga levá-lo.","next":"3A"},{"label":"Explicar sua situação","description":"João decide permanecer e explicar que perdeu o emprego, mas que continua procurando trabalho e realizando pequenos serviços.","next":"3B"}]},"3A":{"id":"3A","kind":"scene","period":"1831","place":"Ruas estreitas da cidade · fuga","title":"A Fuga","paragraphs":["João percebe que o agente está olhando para outro lado.","Então corre o mais rápido que pode.","— “Pare!”","João não olha para trás. Ele atravessa uma rua estreita, passa por algumas casas e consegue despistar o agente.","Mas agora existe um problema maior: a autoridade sabe que ele fugiu.","João passa alguns dias escondido na casa de um conhecido. Sem poder voltar à sua antiga rotina, decide deixar a cidade."],"choices":[{"label":"Viajar para outra região","next":"4A"},{"label":"Procurar proteção","next":"4B"}]},"3B":{"id":"3B","kind":"scene","period":"1831","place":"Praça da cidade · advertência do agente","title":"Explicando Sua Situação","paragraphs":["João respira fundo e explica que perdeu o emprego como ajudante de comerciante.","Ele afirma que está procurando trabalho e que aceita pequenos serviços para conseguir sobreviver.","O agente continua desconfiado, mas João consegue demonstrar que não está simplesmente vivendo de esmolas.","Depois de uma advertência, João é liberado.","Mesmo assim, ele percebe que sua condição de pobreza o deixou vulnerável diante das autoridades."],"choices":[{"label":"Procurar um trabalho fixo","next":"4C"},{"label":"Deixar a cidade","next":"4D"}]},"4A":{"id":"4A","kind":"scene","period":"1832","place":"Estrada · outra região","title":"Longe de Casa","paragraphs":["João deixa sua cidade e começa a viajar.","Durante o caminho, percebe que muitos homens pobres vivem de trabalhos temporários e possuem pouca segurança.","Em uma pequena comunidade, João encontra um grupo de trabalhadores discutindo sobre as dificuldades para conseguir emprego e sobre a presença constante das autoridades."],"choices":[{"label":"Permanecer e procurar trabalho","next":"5A"},{"label":"Continuar viajando","next":"5B"}]},"4B":{"id":"4B","kind":"scene","period":"1832","place":"Casa de um comerciante conhecido","title":"Um Possível Protetor","paragraphs":["João procura um comerciante conhecido de seu antigo patrão.","O comerciante aceita lhe dar pequenos trabalhos, mas deixa claro que João dependerá de sua recomendação para continuar empregado.","João percebe que, para alguém de sua condição, ter um patrão ou uma pessoa influente poderia significar proteção diante das autoridades."],"choices":[{"label":"Aceitar a proteção","next":"5C"},{"label":"Recusar e procurar outro trabalho","next":"5D"}]},"4C":{"id":"4C","kind":"scene","period":"1832","place":"Outra cidade · balcão do comércio","title":"Um Novo Emprego","paragraphs":["João consegue trabalho como ajudante de um comerciante em outra cidade.","O salário é baixo, mas é suficiente para sobreviver.","Algum tempo depois, ele descobre que homens jovens e pobres da região estão sendo procurados para o serviço militar.","O recrutamento era uma realidade que podia atingir especialmente homens livres pobres."],"choices":[{"label":"Permanecer no emprego","next":"5E"},{"label":"Deixar a cidade","next":"5F"}]},"4D":{"id":"4D","kind":"scene","period":"1832","place":"Arredores da cidade · serviços temporários","title":"A Dependência","paragraphs":["João continua fazendo pequenos serviços.","Um comerciante oferece uma oportunidade de trabalho, mas exige que João fique disponível sempre que precisar.","João percebe que possui poucas alternativas: aceitar condições ruins ou voltar a ficar sem renda."],"choices":[{"label":"Aceitar o trabalho","next":"5G"},{"label":"Recusar","next":"5H"}]},"5A":{"id":"5A","kind":"scene","period":"1835","place":"Caminho · grupo reunido para o serviço militar","title":"O Recrutamento","paragraphs":["João continua sua viagem.","Em 1835, durante o período das revoltas regenciais, o governo enfrentava dificuldades para manter tropas e controlar diferentes regiões.","João encontra um grupo de homens que está sendo reunido para o serviço militar.","Um deles olha para João e pergunta:","— “Você não é aquele homem que fugiu de um agente?”","João percebe que sua antiga fuga pode colocá-lo em uma situação ainda mais difícil."],"choices":[{"label":"Tentar explicar sua situação","next":"6A"},{"label":"Fugir novamente","next":"6B"}]},"5B":{"id":"5B","kind":"scene","period":"1835","place":"Comércio · aviso sobre o recrutamento","title":"A Proteção do Comerciante","paragraphs":["O comerciante que emprega João descobre que as autoridades estão procurando homens para o serviço militar.","Ele diz que poderá confirmar que João trabalha para ele.","João percebe que sua segurança depende, em parte, da proteção de alguém com mais influência."],"choices":[{"label":"Pedir que o comerciante o proteja","next":"6C"},{"label":"Não envolver o comerciante","next":"6D"}]},"5C":{"id":"5C","kind":"scene","period":"1836","place":"Serviço · convivência entre trabalhadores","title":"O Trabalhador","paragraphs":["João continua trabalhando.","Mesmo tendo uma ocupação, percebe que outros trabalhadores pobres continuam sendo tratados com desconfiança.","Ele começa a entender que o problema não era apenas sua situação individual, mas a forma como as autoridades lidavam com os homens pobres."],"choices":[{"label":"Ajudar outros trabalhadores","next":"6E"},{"label":"Pensar apenas em sua própria segurança","next":"6F"}]},"5D":{"id":"5D","kind":"scene","period":"1836","place":"Estrada · relatos de homens recrutados","title":"A Partida","paragraphs":["João deixa a cidade antes que possa ser recrutado.","Durante a viagem, encontra trabalhadores que contam histórias de homens pobres que foram afastados de suas famílias e trabalhos depois de serem recrutados.","João percebe que fugir pode resolver seu problema momentaneamente, mas também o impede de construir uma vida estável."],"choices":[{"label":"Procurar uma comunidade para se estabelecer","next":"6G"},{"label":"Continuar viajando","next":"6H"}]},"5E":{"id":"5E","kind":"scene","period":"1837","place":"Repartição local · questionamento","title":"O Conflito","paragraphs":["João consegue trabalho novamente, mas um funcionário local começa a questionar sua origem e sua situação.","— “De onde veio? Quem pode responder por você?”","João percebe que não basta apenas trabalhar. Sua falta de relações com pessoas influentes continua tornando sua posição frágil."],"choices":[{"label":"Pedir uma recomendação ao patrão","next":"6A"},{"label":"Enfrentar o funcionário","next":"6E"}]},"5F":{"id":"5F","kind":"scene","period":"1837","place":"Roda de trabalhadores · conversa sobre trabalho","title":"Entre a Lei e a Pobreza","paragraphs":["João encontra outros homens pobres que discutem a dificuldade de conseguir trabalho.","Eles percebem que, quando não possuem renda ou uma ocupação reconhecida, podem chamar a atenção das autoridades."],"choices":[{"label":"Procurar trabalho junto com eles","next":"6G"},{"label":"Separar-se do grupo","next":"6F"}]},"5G":{"id":"5G","kind":"scene","period":"1838","place":"Vila · influência do responsável local","title":"A Autoridade Local","paragraphs":["João consegue trabalho, mas descobre que o responsável pela região possui grande influência sobre quem será recrutado.","João percebe que as relações pessoais podem fazer diferença para quem será protegido e quem ficará vulnerável."],"choices":[{"label":"Procurar alguém influente","next":"6C"},{"label":"Não depender de ninguém","next":"6D"}]},"5H":{"id":"5H","kind":"scene","period":"1838","place":"Praça · homens reunidos para o serviço militar","title":"Sem Proteção","paragraphs":["João não consegue encontrar alguém que possa protegê-lo.","Pouco tempo depois, ele encontra novamente homens sendo reunidos para o serviço militar.","Ele percebe que não possui patrão influente nem relações capazes de ajudá-lo."],"choices":[{"label":"Tentar demonstrar que possui ocupação","next":"6H"},{"label":"Deixar o local","next":"6B"}]},"6A":{"id":"6A","kind":"scene","period":"1840","place":"Vila pequena · vida sob suspeita","title":"A Vida Sob Suspeita","paragraphs":["João consegue evitar o recrutamento naquele momento.","Mesmo assim, continua vivendo com medo de ser novamente identificado.","Ele percebe que sua pobreza não desapareceu e que qualquer período sem trabalho pode colocá-lo novamente sob suspeita."],"choices":[{"label":"Procurar uma ocupação estável","next":"7A"},{"label":"Continuar escondendo-se","next":"7B"}]},"6B":{"id":"6B","kind":"scene","period":"1840","place":"Estrada · nova fuga","title":"A Fuga Constante","paragraphs":["João consegue escapar novamente.","Mas percebe que cada fuga resolve apenas o problema daquele momento."],"choices":[{"label":"Procurar um emprego em outra cidade","next":"7C"},{"label":"Continuar fugindo","next":"7A"}]},"6C":{"id":"6C","kind":"scene","period":"1841","place":"Comércio do patrão · proteção","title":"O Preço da Proteção","paragraphs":["O comerciante consegue ajudar João a evitar problemas com as autoridades.","Mas João percebe que sua segurança depende da vontade de seu patrão."],"choices":[{"label":"Continuar trabalhando para ele","next":"7B"},{"label":"Procurar independência","next":"7D"}]},"6D":{"id":"6D","kind":"scene","period":"1841","place":"Diante das autoridades · sozinho","title":"Sem Proteção","paragraphs":["João decide não envolver ninguém.","Agora precisa enfrentar sozinho a situação diante das autoridades."],"choices":[{"label":"Tentar demonstrar que possui trabalho","next":"7C"},{"label":"Deixar a cidade","next":"7A"}]},"6E":{"id":"6E","kind":"scene","period":"1842","place":"Entre trabalhadores · ajuda mútua","title":"Entre os Trabalhadores","paragraphs":["João começa a ajudar outros homens pobres a encontrar trabalho.","Ele percebe que muitos enfrentam os mesmos problemas: baixos salários, falta de estabilidade e medo das autoridades."],"choices":[{"label":"Continuar ajudando","next":"7D"},{"label":"Afastar-se dos outros","next":"7C"}]},"6F":{"id":"6F","kind":"scene","period":"1842","place":"Serviço · sobrevivência diária","title":"Pensando Apenas em Sobreviver","paragraphs":["João decide não se envolver com outros trabalhadores.","Ele consegue manter seu trabalho, mas percebe que continua dependendo de sua própria capacidade de sobreviver em uma sociedade onde os pobres possuem pouca proteção."],"choices":[{"label":"Permanecer trabalhando","next":"7B"},{"label":"Procurar uma nova cidade","next":"7A"}]},"6G":{"id":"6G","kind":"scene","period":"1843","place":"Comunidade de trabalhadores","title":"Uma Comunidade","paragraphs":["João decide permanecer próximo de outros trabalhadores.","Eles compartilham informações sobre empregos e ajudam uns aos outros quando algum deles enfrenta problemas."],"choices":[{"label":"Permanecer com a comunidade","next":"7D"},{"label":"Afastar-se para evitar problemas","next":"7C"}]},"6H":{"id":"6H","kind":"scene","period":"1843","place":"Estrada · outra partida","title":"Nova Fuga","paragraphs":["João deixa o local antes de ser abordado.","Mais uma vez, está livre, mas sem trabalho e sem segurança."],"choices":[{"label":"Procurar um emprego","next":"7C"},{"label":"Continuar fugindo","next":"7A"}]},"7A":{"id":"7A","kind":"scene","period":"1845","place":"Anos de deslocamento · estradas e vilas","title":"Sem Escapatória","paragraphs":["João passou anos fugindo de situações que tinham a mesma origem: sua condição de homem pobre.","Ele percebe que não importa quantas cidades atravesse, continuará vulnerável enquanto não possuir estabilidade ou proteção."],"choices":[{"label":"Aceitar a situação e tentar construir uma vida","next":"final-sobreviver"},{"label":"Fugir novamente","next":"final-sem-lugar"}]},"7B":{"id":"7B","kind":"scene","period":"1846","place":"Vila · protegido, mas dependente","title":"Protegido, mas Dependente","paragraphs":["João conseguiu evitar problemas graças ao seu trabalho ou à proteção de outras pessoas.","Porém, percebe que sua segurança depende de relações que podem desaparecer a qualquer momento."],"choices":[{"label":"Continuar dependendo dessa proteção","next":"final-sobreviver"},{"label":"Tentar conquistar independência","next":"final-trabalhadores"}]},"7C":{"id":"7C","kind":"scene","period":"1848","place":"Entre os trabalhadores · a vida dos pobres","title":"A Vida dos Pobres","paragraphs":["João percebe que muitos outros trabalhadores enfrentam problemas semelhantes.","A pobreza não significa apenas ter pouco dinheiro. Também significa ter menos proteção diante das autoridades e depender constantemente de trabalhos instáveis."],"choices":[{"label":"Continuar trabalhando e ajudando outros","next":"final-trabalhadores"},{"label":"Pensar apenas em sobreviver","next":"final-sobreviver"}]},"7D":{"id":"7D","kind":"scene","period":"1850","place":"Reunião de trabalhadores","title":"Uma Escolha Coletiva","paragraphs":["João percebe que sua experiência não é apenas individual.","Outros homens pobres também sofrem com a falta de trabalho, a instabilidade e a pressão das autoridades."],"choices":[{"label":"Permanecer junto aos trabalhadores","next":"final-trabalhadores"},{"label":"Afastar-se para evitar problemas","next":"final-recrutado"}]},"final-sem-lugar":{"id":"final-sem-lugar","kind":"ending","tier":"silence","label":"Final 1 · Desfecho ruim","title":"O Homem Sem Lugar","paragraphs":["João continua fugindo.","Ele não consegue manter um trabalho por muito tempo e passa de uma cidade para outra para evitar as autoridades.","Sua pobreza continua tornando sua vida instável.","A liberdade que João procura existe, mas é uma liberdade marcada pela insegurança: sem dinheiro, sem proteção e sempre com medo de voltar a ser tratado como um homem sem ocupação.","A história de João mostra como a pobreza podia colocar os homens livres das classes baixas em uma posição de grande vulnerabilidade diante das autoridades do Império."]},"final-recrutado":{"id":"final-recrutado","kind":"ending","tier":"discovery","label":"Final 2 · Desfecho ruim","title":"O Recrutado","paragraphs":["João decide se afastar dos outros trabalhadores e continua vulnerável.","Em determinado momento, acaba sendo alcançado pelo recrutamento.","Para João, o serviço militar representa a perda da possibilidade de escolher livremente onde trabalhar e viver.","Sua condição de homem livre pobre contribuiu para deixá-lo mais vulnerável ao recrutamento e ao controle das autoridades."]},"final-sobreviver":{"id":"final-sobreviver","kind":"ending","tier":"resistance","label":"Final 3 · Desfecho mediano","title":"Sobreviver","paragraphs":["João consegue manter um trabalho e construir uma vida simples.","Ele continua pobre e precisa trabalhar constantemente para sobreviver, mas consegue evitar novos conflitos com as autoridades.","Sua história não termina com uma grande mudança social.","João apenas consegue conquistar algo que para muitos homens pobres era difícil: estabilidade suficiente para trabalhar e sustentar a própria vida sem estar constantemente sob suspeita ou ameaça."]},"final-trabalhadores":{"id":"final-trabalhadores","kind":"ending","tier":"rupture","label":"Final 4 · Desfecho bom","title":"A Força dos Trabalhadores","paragraphs":["Depois de tudo o que viveu, João percebe que seu problema não era apenas individual.","Outros trabalhadores pobres enfrentavam dificuldades semelhantes: trabalhos instáveis, baixos rendimentos, dependência de pessoas mais influentes e vulnerabilidade diante das autoridades.","João decide permanecer próximo desses trabalhadores e ajudá-los a encontrar trabalho e a enfrentar juntos suas dificuldades.","Ele não fica rico nem muda completamente sua posição social.","Sua conquista é perceber que os problemas enfrentados pelos pobres faziam parte de uma estrutura maior e que a união entre trabalhadores podia criar formas de resistência e proteção."]}},"caue":{"2":{"id":"2","kind":"scene","period":"1850","place":"Fazenda de café · Vale do Paraíba","title":"A Vida na Fazenda","paragraphs":["Cauê é um homem negro escravizado que trabalha em uma plantação de café. Todos os dias enfrenta uma rotina pesada, sob ordens constantes de seu proprietário e de seus feitores.","Sua única companhia era seu irmão Joaquim. Há alguns meses, Joaquim foi vendido para outra fazenda, deixando Cauê praticamente sozinho.","Com poucas esperanças para o futuro, um acontecimento tem o potencial para mudar tudo: Cauê ouve comentários de que pessoas de fora da fazenda estão começando a questionar a escravidão."],"choices":[{"label":"Tentar descobrir mais","description":"Cauê procura entender o que está acontecendo sem chamar atenção.","next":"3A"},{"label":"Continuar em silêncio","description":"Cauê decide evitar riscos e concentra-se em sobreviver à rotina da fazenda.","next":"3B"}]},"3A":{"id":"3A","kind":"scene","period":"1850","place":"Arredores da fazenda · fim do dia","title":"Rumores de Mudança","paragraphs":["Cauê descobre que alguns trabalhadores ouviram falar de pessoas que defendiam o fim da escravidão. As informações são vagas, mas pela primeira vez em muito tempo ele percebe que sua situação não é necessariamente permanente.","Ao mesmo tempo, ele teme que falar demais possa trazer problemas para si e para outras pessoas."],"choices":[{"label":"Compartilhar o que descobriu","description":"Cauê conversa discretamente com pessoas em quem confia.","next":"4A"},{"label":"Guardar a informação","description":"Ele prefere observar os acontecimentos antes de confiar em alguém.","next":"4B"}]},"3B":{"id":"3B","kind":"scene","period":"1850","place":"Senzala · noite","title":"A Saudade de Joaquim","paragraphs":["Sozinho depois da venda de Joaquim, Cauê tenta manter as lembranças do irmão vivas. Outros trabalhadores também contam histórias de familiares que foram separados.","A conversa faz Cauê perceber que sua experiência é compartilhada por muitas outras pessoas escravizadas."],"choices":[{"label":"Conversar com outros trabalhadores","description":"Cauê procura apoio entre aqueles que vivem situações parecidas.","next":"4C"},{"label":"Manter-se afastado","description":"Ele evita criar vínculos para não colocar outras pessoas em risco.","next":"4D"}]},"4A":{"id":"4A","kind":"scene","period":"1851","place":"Área de trabalho · conversa discreta","title":"Uma Rede de Apoio","paragraphs":["Cauê descobre que alguns trabalhadores trocam informações e tentam ajudar pessoas separadas de suas famílias. Ninguém sabe ao certo o que acontecerá no futuro, mas existe uma pequena rede de confiança."],"choices":[{"label":"Ajudar a rede","next":"5A"},{"label":"Apenas ouvir","next":"5B"}]},"4B":{"id":"4B","kind":"scene","period":"1851","place":"Casa-grande · trabalho cotidiano","title":"Entre o Medo e a Esperança","paragraphs":["Cauê continua trabalhando, mas passa a prestar atenção às conversas que acontecem na fazenda. Aos poucos, percebe que o mundo fora dali está discutindo mudanças que podem afetar sua vida."],"choices":[{"label":"Procurar alguém de confiança","next":"5C"},{"label":"Esperar uma oportunidade","next":"5D"}]},"4C":{"id":"4C","kind":"scene","period":"1851","place":"Senzala · conversa entre trabalhadores","title":"Uma Dor Compartilhada","paragraphs":["Os trabalhadores falam sobre famílias separadas, jornadas exaustivas e a falta de liberdade. Cauê percebe que a perda de Joaquim faz parte de um problema muito maior."],"choices":[{"label":"Apoiar os outros","next":"5E"},{"label":"Pensar primeiro em Joaquim","next":"5F"}]},"4D":{"id":"4D","kind":"scene","period":"1851","place":"Plantação · rotina de trabalho","title":"O Isolamento","paragraphs":["Cauê evita conversas e mantém sua rotina. Mesmo assim, a ausência de Joaquim continua presente em seus pensamentos.","Um dia, ele percebe que um novo trabalhador conhece pessoas que já ouviram falar de Joaquim."],"choices":[{"label":"Perguntar sobre Joaquim","next":"5G"},{"label":"Não perguntar","next":"5H"}]},"5A":{"id":"5A","kind":"scene","period":"1852","place":"Arredores da fazenda · encontro reservado","title":"A Confiança","paragraphs":["Cauê começa a participar de uma pequena rede de apoio entre pessoas escravizadas. As conversas dão força para quem se sente sozinho, mas também deixam claro que qualquer mudança dependerá de muita coragem e união.","Uma notícia chega: pessoas de fora estão procurando maneiras de ajudar escravizados que desejam alcançar a liberdade."],"choices":[{"label":"Confiar na notícia","next":"6A"},{"label":"Esperar mais informações","next":"6B"}]},"5B":{"id":"5B","kind":"scene","period":"1852","place":"Senzala · depois do trabalho","title":"Ouvindo em Silêncio","paragraphs":["Cauê continua apenas ouvindo as conversas. Com o tempo, percebe que outras pessoas também estão buscando notícias sobre mudanças na escravidão.","Ele começa a acreditar que permanecer completamente isolado pode ser tão difícil quanto correr algum risco."],"choices":[{"label":"Aproximar-se dos outros","next":"6C"},{"label":"Continuar sozinho","next":"6D"}]},"5C":{"id":"5C","kind":"scene","period":"1852","place":"Arredores da fazenda · conversa com um conhecido","title":"Uma Pessoa de Confiança","paragraphs":["Cauê encontra alguém disposto a conversar. Essa pessoa conta que existem debates cada vez maiores sobre a escravidão e que algumas pessoas livres estão tentando ajudar escravizados.","A informação não garante uma mudança imediata, mas cria uma possibilidade que antes parecia distante."],"choices":[{"label":"Manter contato","next":"6E"},{"label":"Afastar-se por enquanto","next":"6F"}]},"5D":{"id":"5D","kind":"scene","period":"1852","place":"Plantação · trabalho cotidiano","title":"Esperando a Oportunidade","paragraphs":["Cauê continua trabalhando e observando. Ele aprende a reconhecer quando as conversas mudam e percebe que algumas pessoas da fazenda também estão insatisfeitas com a situação.","Uma nova informação sobre Joaquim chega até ele."],"choices":[{"label":"Perguntar sobre Joaquim","next":"6G"},{"label":"Guardar a informação","next":"6H"}]},"5E":{"id":"5E","kind":"scene","period":"1852","place":"Senzala · apoio entre trabalhadores","title":"Juntos","paragraphs":["Cauê passa a ajudar outros trabalhadores sempre que pode. Pequenos gestos de solidariedade fazem com que ele deixe de se sentir completamente sozinho.","Ao mesmo tempo, ele percebe que as pessoas precisam pensar no futuro e na possibilidade de liberdade."],"choices":[{"label":"Continuar ajudando","next":"6A"},{"label":"Concentrar-se na própria liberdade","next":"6C"}]},"5F":{"id":"5F","kind":"scene","period":"1852","place":"Plantação · notícia sobre Joaquim","title":"Procurando o Irmão","paragraphs":["Cauê descobre que Joaquim foi levado para outra região e que talvez alguém saiba mais sobre seu destino. A notícia traz esperança, mas também mostra como a separação das famílias era consequência da escravidão.","Ele precisa decidir se continua procurando respostas ou se passa a olhar para sua própria situação."],"choices":[{"label":"Continuar procurando Joaquim","next":"6G"},{"label":"Pensar no próprio futuro","next":"6E"}]},"5G":{"id":"5G","kind":"scene","period":"1852","place":"Senzala · conversa sobre Joaquim","title":"Uma Pista","paragraphs":["A pessoa que conhece histórias sobre Joaquim não sabe exatamente onde ele está, mas confirma que ele foi vendido para outra fazenda.","Cauê sente a dor da separação novamente, mas também percebe que outras pessoas estão dispostas a ajudá-lo."],"choices":[{"label":"Aceitar ajuda","next":"6G"},{"label":"Não envolver ninguém","next":"6H"}]},"5H":{"id":"5H","kind":"scene","period":"1852","place":"Plantação · fim do dia","title":"Sem Respostas","paragraphs":["Cauê decide não perguntar. A ausência de Joaquim continua sendo parte de sua vida, mas ele percebe que não pode depender apenas de respostas que talvez nunca cheguem.","Ao longe, ouve novamente comentários sobre mudanças na escravidão."],"choices":[{"label":"Prestar atenção","next":"6B"},{"label":"Ignorar os rumores","next":"6D"}]},"6A":{"id":"6A","kind":"scene","period":"1853","place":"Arredores da fazenda · rede de apoio","title":"Uma Esperança","paragraphs":["A rede de apoio cresce lentamente. Cauê percebe que a solidariedade ajuda as pessoas a enfrentar a rotina e a manter viva a esperança de liberdade.","As notícias sobre o movimento contra a escravidão continuam chegando de forma fragmentada."],"choices":[{"label":"Continuar unido aos outros","next":"7A"},{"label":"Buscar uma mudança para si","next":"7B"}]},"6B":{"id":"6B","kind":"scene","period":"1853","place":"Fazenda · observando os acontecimentos","title":"Esperar Não Basta","paragraphs":["Cauê espera por informações mais claras, mas percebe que o tempo passa e sua condição permanece a mesma. Ele entende que apenas esperar pode não mudar sua vida.","Uma pessoa em quem confia fala sobre a possibilidade de buscar ajuda fora da fazenda."],"choices":[{"label":"Aceitar ajuda","next":"7B"},{"label":"Permanecer onde está","next":"7C"}]},"6C":{"id":"6C","kind":"scene","period":"1853","place":"Senzala · conversa entre trabalhadores","title":"A União","paragraphs":["Cauê se aproxima novamente dos outros trabalhadores. A união não elimina os problemas, mas faz com que ninguém precise enfrentá-los completamente sozinho.","Alguns começam a acreditar que a escravidão não durará para sempre."],"choices":[{"label":"Apoiar essa esperança","next":"7D"},{"label":"Continuar cauteloso","next":"7C"}]},"6D":{"id":"6D","kind":"scene","period":"1853","place":"Plantação · rotina","title":"Sobreviver","paragraphs":["Cauê continua sozinho e concentra-se em sobreviver à rotina. Ele consegue evitar alguns conflitos, mas a falta de apoio torna seu futuro incerto.","A ideia de liberdade continua distante, mas já não parece impossível."],"choices":[{"label":"Procurar apoio","next":"7C"},{"label":"Continuar sozinho","next":"7A"}]},"6E":{"id":"6E","kind":"scene","period":"1853","place":"Arredores da fazenda · encontro de confiança","title":"Um Caminho Possível","paragraphs":["Cauê mantém contato com pessoas que defendem mudanças. Elas não podem prometer que tudo será resolvido, mas mostram que existem pessoas dispostas a enfrentar a escravidão.","Pela primeira vez, Cauê começa a imaginar uma vida diferente."],"choices":[{"label":"Manter-se próximo da rede","next":"7D"},{"label":"Agir pensando apenas em si","next":"7B"}]},"6F":{"id":"6F","kind":"scene","period":"1853","place":"Fazenda · silêncio","title":"Afastado","paragraphs":["Cauê se afasta das conversas para evitar riscos. A rotina continua, mas ele percebe que o isolamento não devolve Joaquim nem muda sua condição.","Uma nova notícia sobre mudanças no país chega à fazenda."],"choices":[{"label":"Ouvir a notícia","next":"7C"},{"label":"Ignorá-la","next":"7A"}]},"6G":{"id":"6G","kind":"scene","period":"1853","place":"Fazenda · informações sobre Joaquim","title":"A Lembrança de Joaquim","paragraphs":["Cauê não consegue encontrar Joaquim, mas descobre que ele continua trabalhando em outra fazenda. A informação não resolve a separação, mas confirma que o irmão ainda faz parte de sua esperança.","Cauê decide que também precisa pensar no próprio futuro."],"choices":[{"label":"Buscar apoio para mudar sua vida","next":"7D"},{"label":"Continuar procurando Joaquim","next":"7C"}]},"6H":{"id":"6H","kind":"scene","period":"1853","place":"Plantação · fim do dia","title":"Sem Certezas","paragraphs":["Cauê guarda as informações para si. A vida continua difícil, mas os rumores sobre o fim da escravidão tornam-se cada vez mais frequentes.","Ele precisa decidir se continuará apenas esperando ou se tentará construir uma nova possibilidade."],"choices":[{"label":"Aproximar-se de outros trabalhadores","next":"7D"},{"label":"Continuar esperando","next":"7A"}]},"7A":{"id":"7A","kind":"scene","period":"1854","place":"Fazenda de café · rotina","title":"O Peso da Espera","paragraphs":["Cauê continua na fazenda. A esperança existe, mas a realidade ainda é marcada pela falta de liberdade e pela separação de sua família.","Ele percebe que sobreviver não significa aceitar aquela situação como justa."],"choices":[{"label":"Continuar resistindo junto aos outros","next":"final-resistencia"},{"label":"Desistir de procurar mudanças","next":"final-cativeiro"}]},"7B":{"id":"7B","kind":"scene","period":"1854","place":"Arredores da fazenda · decisão","title":"Uma Escolha Difícil","paragraphs":["Cauê começa a buscar uma mudança para sua própria vida. Ele sabe que não controla as decisões do proprietário, mas percebe que pode escolher em quem confiar e como manter viva sua esperança.","A ajuda de outras pessoas torna-se cada vez mais importante."],"choices":[{"label":"Confiar na rede de apoio","next":"final-liberdade"},{"label":"Continuar sozinho","next":"final-sobrevivencia"}]},"7C":{"id":"7C","kind":"scene","period":"1854","place":"Plantação de café · entre trabalhadores","title":"Uma Vida Compartilhada","paragraphs":["Cauê percebe que sua história se mistura à de muitos outros trabalhadores escravizados. Famílias são separadas, pessoas vivem sob controle e a liberdade continua sendo uma esperança.","Mesmo sem saber como o futuro terminará, ele entende que não está sozinho."],"choices":[{"label":"Permanecer junto aos outros","next":"final-resistencia"},{"label":"Pensar apenas em sobreviver","next":"final-sobrevivencia"}]},"7D":{"id":"7D","kind":"scene","period":"1854","place":"Arredores da fazenda · rede de apoio","title":"A Esperança Coletiva","paragraphs":["Cauê continua próximo das pessoas que o apoiaram. A rede não consegue apagar a violência da escravidão, mas oferece solidariedade e esperança.","Com as discussões sobre o fim da escravidão crescendo no país, Cauê acredita que sua vida pode mudar."],"choices":[{"label":"Continuar unido aos outros","next":"final-liberdade"},{"label":"Afastar-se para evitar riscos","next":"final-resistencia"}]},"final-cativeiro":{"id":"final-cativeiro","kind":"ending","tier":"bad","label":"Final 1 · Desfecho ruim","title":"A Esperança Adiada","paragraphs":["Cauê permanece preso à rotina da fazenda e decide não procurar novas possibilidades. A ausência de Joaquim continua sendo parte de sua vida.","Sua história mostra como a escravidão limitava as escolhas de pessoas escravizadas e podia separar famílias sem que elas tivessem controle sobre essas decisões."]},"final-sobrevivencia":{"id":"final-sobrevivencia","kind":"ending","tier":"medium","label":"Final 2 · Desfecho mediano","title":"Sobreviver","paragraphs":["Cauê consegue manter alguns vínculos e atravessar os anos seguintes sem perder completamente a esperança.","Sua vida continua marcada pela escravidão, pela separação de Joaquim e pela falta de liberdade. Ainda assim, ele encontra força na memória do irmão e nas pessoas que o cercam."]},"final-resistencia":{"id":"final-resistencia","kind":"ending","tier":"rupture","label":"Final 3 · Desfecho bom","title":"A Força da União","paragraphs":["Cauê decide permanecer próximo dos outros trabalhadores. A solidariedade não acaba imediatamente com a escravidão, mas impede que ele enfrente tudo sozinho.","Ao compartilhar informações, apoiar outras pessoas e manter viva a esperança de liberdade, Cauê percebe que sua história faz parte de uma luta coletiva contra uma estrutura que separava famílias e negava liberdade."]},"final-liberdade":{"id":"final-liberdade","kind":"ending","tier":"rupture","label":"Final 4 · Desfecho bom","title":"Um Novo Caminho","paragraphs":["Cauê mantém contato com uma rede de apoio e consegue se aproximar de pessoas que defendem o fim da escravidão. O futuro ainda é incerto, mas a possibilidade de liberdade deixa de parecer apenas um sonho distante.","A lembrança de Joaquim permanece com ele. Cauê entende que sua busca por uma vida livre também representa a esperança de que outras famílias não precisem passar pela mesma separação."]}}};

const characters=[
 {id:'joao',name:'João de Alcantra',socialClass:'Classe Baixa',period:'1829–1900',record:'Registro disponível',playable:true,variant:'joao'},
 {id:'caue',name:'Cauê Borges',socialClass:'Classe Escrava',period:'1829–1900',record:'Registro disponível',playable:true,variant:'caue'},
 {id:'aline',name:'Aline Moreira',socialClass:'Esposa Classe Alta',period:'1829–1900',record:'Registro disponível',playable:true,variant:'aline'}
];
const intro=[
 'Você foi chamado por uma empresa de tecnologia de alto desempenho para testar seu novo produto. Um óculos de realidade virtual que tem como propósito revisitar momentos do passado através dos relatos da época.',
 'Agora você escolherá seu personagem. Você acompanhará a jornada do personagem escolhido nos anos 1829 até 1900. Escolha seu personagem para começar sua jornada.'
];
const state={character:null,sceneId:'2'};
const main=document.getElementById('main');
const meta=document.getElementById('journeyMeta');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function arrowIcon(cls=''){
 return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h13"/><path d="m13 6 6 6-6 6"/></svg>`;
}
function lockIcon(cls=''){
 return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>`;
}
function playIcon(cls=''){
 return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m8 5 11 7-11 7z"/></svg>`;
}
function restartIcon(cls=''){
 return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 11a8 8 0 0 0-14.9-4"/><path d="M4 4v5h5"/><path d="M4 13a8 8 0 0 0 14.9 4"/><path d="M20 20v-5h-5"/></svg>`;
}

// This is the same inline silhouette construction used by the original bundle.
function silhouette(v){
 const head=v==='aline'
   ? '<circle cx="60" cy="15" r="10"/>'
   : v==='caue'
     ? '<circle cx="42" cy="36" r="9"/><circle cx="80" cy="36" r="9"/>'
     : '';
 const hair=v==='aline'
   ? '<ellipse cx="60" cy="33" rx="21" ry="18"/><ellipse cx="40" cy="48" rx="4.5" ry="9"/><ellipse cx="80" cy="48" rx="4.5" ry="9"/>'
   : v==='caue'
     ? '<circle cx="44" cy="34" r="8"/><circle cx="54" cy="28" r="8"/><circle cx="66" cy="28" r="8"/><circle cx="76" cy="34" r="8"/>'
     : '<ellipse cx="60" cy="35" rx="21" ry="16"/>';
 const body={
  aline:'M60 94c-30 0-52 24-56 52-1 6-1 10-1 14h114c0-4 0-8-1-14-4-28-26-52-56-52z',
  joao:'M60 98c-30 0-54 26-54 62h108c0-36-24-62-54-62z',
  caue:'M60 96c-24 0-42 18-50 40-4 10-6 18-6 24h112c0-6-2-14-6-24-8-22-26-40-50-40z'
 }[v];
 const mark=v==='aline'
   ? '<path d="M47 106q13 11 26 0" fill="none" stroke="hsl(40 40% 82% / 0.5)" stroke-width="1.4" stroke-linecap="round"/>'
   : v==='joao'
     ? '<path d="M50 102l10 12 10-12" fill="none" stroke="hsl(40 40% 82% / 0.4)" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/>'
     : '<path d="M26 124q34-16 68 0" fill="none" stroke="hsl(40 40% 82% / 0.25)" stroke-width="1.4" stroke-linecap="round"/>';
 return `<svg viewBox="0 0 120 160" fill="currentColor" aria-hidden="true" class="cameo__silhouette" preserveAspectRatio="xMidYMax meet">${head}<path d="${body}"/><rect x="50" y="62" width="20" height="44" rx="9"/><ellipse cx="60" cy="52" rx="20" ry="25"/>${hair}${mark}</svg>`;
}

function header(){
 const journey=state.character?`Jornada: ${esc(state.character.name)}`:'Seleção de personagem';
 meta.className='hud__meta hidden items-center gap-3 md:flex';
 meta.innerHTML=`<span>Arquivo 1829–1900</span><span class="hud__sep">·</span><span>${journey}</span><span class="hud__sep">·</span><span>Fidelidade 94%</span>`;
}
function render(){
 header();
 if(!state.character){introView();return;}
 const s=SCENES[state.character.id]?.[state.sceneId];
 if(!s){state.character=null;introView();return;}
 if(s.kind==='ending'){endingView(s);return;}
 sceneView(s);
 window.scrollTo({top:0,behavior:'smooth'});
}

function introView(){
 main.innerHTML=`<div class="mx-auto w-full max-w-5xl recreate-enter">
   <div class="panel-scene">
     <div class="scene-meta"><span>Etapa inicial</span><span class="hud__sep">·</span><span>Seleção de personagem</span><span class="hud__sep">·</span><span>Brasil Imperial</span></div>
     <h1 class="scene-title text-balance">Escolha Seu Personagem</h1>
     <div class="scene-rule"></div>
     <div class="scene-prose">${intro.map(p=>`<p>${esc(p)}</p>`).join('')}</div>
   </div>
   <div class="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">${characters.map(c=>card(c)).join('')}</div>
   <div id="lockedMessage" class="mt-6 hidden flex items-start gap-3 rounded-lg border border-border/70 bg-secondary/40 px-4 py-3 font-ui text-[11px] uppercase leading-relaxed tracking-[0.12em] text-muted-foreground"></div>
   <p class="mt-6 flex items-center gap-2 font-ui text-[10px] uppercase tracking-[0.16em] text-muted-foreground">${arrowIcon('size-3 shrink-0 text-primary')}<span>Selecione um personagem para iniciar a jornada</span></p>
 </div>`;
 document.querySelectorAll('.card-character').forEach(el=>el.addEventListener('click',()=>selectCharacter(el.dataset.id)));
}
function card(c){
 const locked=!c.playable;
 return `<button type="button" data-state="${locked?'locked':'available'}" data-id="${c.id}" aria-disabled="${locked}" class="card-character">
   ${locked?'':`<span class="card-character__badge">${playIcon('size-2.5')}Jogável</span>`}
   <div class="card-character__portrait"><div class="cameo">${silhouette(c.variant)}</div></div>
   <div class="card-character__body">
     <h3 class="card-character__name">${esc(c.name)}</h3>
     <p class="card-character__class">${esc(c.socialClass)}</p>
     <p class="card-character__status${locked?'':' card-character__status--ready'}">${locked?lockIcon('size-3'):''}${esc(c.record)}</p>
     ${locked?'':`<span class="card-character__cta">${arrowIcon('size-3')}Iniciar jornada</span>`}
   </div>
 </button>`;
}
function selectCharacter(id){
 const c=characters.find(x=>x.id===id);if(!c)return;
 if(!c.playable){
   const box=document.getElementById('lockedMessage');
   box.innerHTML=`${lockIcon('mt-px size-3.5 shrink-0 text-accent')}<span>A jornada de ${esc(c.name)} está disponível. Você acompanhará sua história durante o período do Brasil Imperial.</span>`;
   box.classList.remove('hidden');
   return;
 }
 state.character=c;state.sceneId='2';render();
}
function sceneView(s){
 const first=state.character?.name?.split(' ')[0]||'';
 main.innerHTML=`<div class="mx-auto w-full max-w-3xl recreate-enter">
   <article class="panel-scene">
     <div class="scene-meta"><span>${esc(s.period)}</span><span class="hud__sep">·</span><span>${esc(s.place)}</span></div>
     <h1 class="scene-title text-balance">${esc(s.title)}</h1>
     <div class="scene-rule"></div>
     <div class="scene-prose">${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div>
   </article>
   <div class="mt-7 space-y-3">
     <p class="font-ui text-[10px] uppercase tracking-[0.2em] text-muted-foreground">O que ${esc(first)} faz?</p>
     ${s.choices.map((c,i)=>`<button type="button" class="btn-choice recreate-choice" style="animation-delay:${.35+i*.08}s" data-next="${esc(c.next)}">${arrowIcon('btn-choice__icon')}<span><span class="btn-choice__label block">${esc(c.label)}</span>${c.description?`<span class="btn-choice__desc block">${esc(c.description)}</span>`:''}</span></button>`).join('')}
   </div>
 </div>`;
 document.querySelectorAll('.btn-choice').forEach(b=>b.addEventListener('click',()=>{state.sceneId=b.dataset.next;render()}));
}
function endingView(e){
 main.innerHTML=`<div class="mx-auto w-full max-w-3xl recreate-enter">
   <section class="ending" data-tier="${esc(e.tier)}">
     <div class="ending__eyebrow">${esc(e.label)}</div>
     <h1 class="ending__title">${esc(e.title)}</h1>
     <div class="ending__rule"></div>
     <div class="ending__body">${e.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div>
     <div class="mt-8 flex flex-wrap items-center justify-center gap-3">
       <button type="button" class="control-ghost control-ghost--primary" id="journeyAgain">${restartIcon('size-3.5')}Reiniciar jornada</button>
       <button type="button" class="control-ghost" id="sessionAgain">Escolher personagem</button>
     </div>
   </section>
 </div>`;
 document.getElementById('journeyAgain').onclick=()=>{state.sceneId='2';render()};
 document.getElementById('sessionAgain').onclick=()=>{state.character=null;state.sceneId='2';render()};
}

document.getElementById('restart').addEventListener('click',()=>{state.character=null;state.sceneId='2';render()});
render();
